export default function WarehouseShelves({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const fill = p.fill ?? 0;
  const door = p.door ?? 0;
  const rows = [76, 112, 148];
  const cols = [44, 80, 116];
  const boxes: any[] = [];
  let n = 0;
  rows.forEach((y, r) => {
    cols.forEach((x, k) => {
      const t = Math.min(1, Math.max(0, fill * 9 - n));
      n++;
      const dy = (1 - t) * -10;
      boxes.push(
        <g key={`${r}-${k}`} opacity={t} transform={`translate(0 ${dy})`}>
          <rect x={x} y={y - 22} width={28} height={22} rx={2} fill={c.bg} stroke={c.primary} strokeWidth={sw} />
          <path d={`M${x} ${y - 14} L${x + 28} ${y - 14}`} stroke={c.primary} strokeWidth={sw} />
          {r === 1 && k === 1 ? <rect x={x + 10} y={y - 14} width={8} height={5} fill={c.accent} stroke={c.accent} strokeWidth={sw} /> : null}
        </g>
      );
    });
  });
  const dh = 40 * (1 - door);
  return (
    <g strokeLinecap="round" strokeLinejoin="round" fill="none">
      <clipPath id={`${uid}-c`}><rect x={142} y={110} width={32} height={58} /></clipPath>
      <path d="M24 168 L176 168" stroke={c.primary} strokeWidth={sw} />
      <path d="M30 168 L30 40 M154 168 L154 40 M30 40 L154 40" stroke={c.primary} strokeWidth={sw} />
      {rows.map((y) => (
        <path key={y} d={`M30 ${y} L154 ${y}`} stroke={c.primary} strokeWidth={sw} />
      ))}
      {boxes}
      <rect x={142} y={110} width={32} height={58} stroke={c.primary} strokeWidth={sw} opacity={0} />
      <path d="M162 168 L162 120 L176 120 L176 168" stroke={c.primary} strokeWidth={sw} opacity={0} />
      <g clipPath={`url(#${uid}-c)`}>
        <path d="M144 168 L144 112 L172 112 L172 168" stroke={c.primary} strokeWidth={sw} opacity={0.4} />
        <rect x={144} y={112 - 0} width={28} height={dh + 0.01} transform={`translate(0 ${-0})`} fill={c.surface} stroke={c.primary} strokeWidth={sw} opacity={door > 0.98 ? 0 : 1} />
        <path d={`M144 ${118 + dh * 0.0} L172 118 M144 126 L172 126`} stroke={c.primary} strokeWidth={sw} opacity={0} />
      </g>
    </g>
  );
}

