export default function ShoppingCart({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const fill = p.fill ?? 0;
  const roll = p.roll ?? 0;
  const dx = roll * 14 - 7;
  const spin = roll * 360;
  const e = (t: number) => Math.min(1, Math.max(0, t));
  const d1 = 1 - e(fill * 2);
  const d2 = 1 - e(fill * 2 - 0.6);
  const wheel = (cx: number) => (
    <g>
      <circle cx={cx} cy={162} r={9} fill={c.bg} stroke={c.primary} strokeWidth={sw} />
      <g transform={`rotate(${spin} ${cx} 162)`}>
        <path d={`M${cx - 5} 162 L${cx + 5} 162`} stroke={c.primary} strokeWidth={sw} />
        <path d={`M${cx} 157 L${cx} 167`} stroke={c.primary} strokeWidth={sw} />
      </g>
    </g>
  );
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <path d="M24 176 L176 176" stroke={c.border} strokeWidth={sw} opacity={0.6} />
      <g transform={`translate(${dx} 0)`}>
        <g transform={`translate(0 ${-d1 * 40})`} opacity={1 - d1 * 0.4}>
          <rect x={64} y={64} width={30} height={30} rx={4} fill={c.accent} stroke={c.primary} strokeWidth={sw} />
          <path d="M72 74 L86 74" stroke={c.primary} strokeWidth={sw} />
        </g>
        <g transform={`translate(0 ${-d2 * 44})`} opacity={1 - d2 * 0.4}>
          <rect x={102} y={72} width={28} height={22} rx={4} fill={c.surface} stroke={c.primary} strokeWidth={sw} />
          <path d="M108 72 L108 62 Q116 54 124 62 L124 72" fill="none" stroke={c.primary} strokeWidth={sw} />
        </g>
        <path d="M20 40 L38 40 L56 128 L146 128" fill="none" stroke={c.primary} strokeWidth={sw} />
        <path d="M44 74 L170 74 L158 118 L52 118 Z" fill={c.surface} fillOpacity={0.35} stroke={c.primary} strokeWidth={sw} />
        <path d="M80 74 L84 118 M114 74 L112 118 M140 74 L135 118" stroke={c.primary} strokeWidth={sw} opacity={0.5} />
        <path d="M56 128 L62 148 L138 148" fill="none" stroke={c.primary} strokeWidth={sw} />
        {wheel(70)}
        {wheel(132)}
      </g>
    </g>
  );
}

