export default function CreditCard({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const flip = p.flip ?? 0; // 0 = back, 1 = front
  const tap = p.tap ?? 0;
  const t = flip * 2 - 1; // -1..1
  const sx = Math.max(0.06, Math.abs(t));
  const front = flip >= 0.5;
  const w = (n: number) => (tap > n ? 1 : 0);
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <ellipse cx={100} cy={168} rx={60} ry={6} fill={c.black} opacity={0.1} />
      <g fill="none" stroke={c.accent} strokeWidth={sw}>
        <path d="M180 90 q6 10 0 20" opacity={Math.min(1, tap * 3)} />
        <path d="M186 82 q9 18 0 36" opacity={Math.max(0, Math.min(1, tap * 3 - 1))} />
        <path d="M192 74 q12 26 0 52" opacity={Math.max(0, Math.min(1, tap * 3 - 2))} />
      </g>
      <g transform={`translate(100 100) scale(${sx} 1) translate(-100 -100)`}>
        <rect x={25} y={52} width={150} height={96} rx={12} fill={c.surface} stroke={c.primary} strokeWidth={sw} />
        {front ? (
          <g fill="none" stroke={c.primary} strokeWidth={sw}>
            <rect x={42} y={78} width={26} height={20} rx={4} fill={c.accent} />
            <path d="M42 88 H68 M55 78 V98" />
            <path d="M42 124 H100 M42 134 H76" />
            <circle cx={142} cy={126} r={8} />
            <circle cx={154} cy={126} r={8} />
          </g>
        ) : (
          <g fill="none" stroke={c.primary} strokeWidth={sw}>
            <rect x={26} y={66} width={148} height={20} fill={c.accent} opacity={0.9} />
            <path d="M42 108 H120 M42 120 H100" />
            <rect x={130} y={102} width={30} height={20} rx={4} />
          </g>
        )}
      </g>
    </g>
  );
}

