export default function Calendar({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const flip = p.flip ?? 0;
  const mark = p.mark ?? 0;
  const dots: JSX.Element[] = [];
  for (let r = 0; r < 4; r++) {
    for (let k = 0; k < 5; k++) {
      dots.push(<circle key={r * 5 + k} cx={56 + k * 22} cy={104 + r * 18} r={1.5} fill={c.primary} stroke={c.primary} strokeWidth={sw} />);
    }
  }
  // top page flips up about the binding at y=56; scaleY goes 1 -> -1 and shrinks into the header area
  const sy = Math.cos(flip * Math.PI);
  const len = 2 * Math.PI * 11;
  return (
    <g strokeLinecap="round" strokeLinejoin="round" fill="none">
      <path d="M36 56 L164 56 L164 172 L36 172 Z" fill={c.surface} stroke={c.primary} strokeWidth={sw} />
      <path d="M36 74 L164 74" stroke={c.primary} strokeWidth={sw} />
      {dots}
      <circle cx={100} cy={122} r={11} stroke={c.accent} strokeWidth={sw} strokeDasharray={`${len * mark} ${len}`} transform="rotate(-90 100 122)" />
      <circle cx={100} cy={122} r={3} fill={c.accent} stroke="none" opacity={mark} />
      <g transform={`translate(0 56) scale(1 ${sy}) translate(0 -56)`}>
        <path d="M36 56 L164 56 L164 170 L36 170 Z" fill={c.surface2} stroke={c.primary} strokeWidth={sw} opacity={sy > 0 ? 1 : 0} />
        <path d="M36 56 L164 56 L164 -0 L36 -0 Z" fill={c.surface2} stroke={c.primary} strokeWidth={sw} opacity={sy > 0 ? 0 : 1} />
      </g>
      <path d="M60 90 L120 90" stroke={c.primary} strokeWidth={sw} opacity={sy > 0 ? sy : 0} />
      <path d="M60 110 L90 110" stroke={c.primary} strokeWidth={sw} opacity={sy > 0 ? sy : 0} />
      <path d="M60 40 L60 62 M100 40 L100 62 M140 40 L140 62" stroke={c.primary} strokeWidth={sw} />
    </g>
  );
}

