export default function GrowthChart({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const draw = p.draw ?? 0;
  const peak = p.peak ?? 0;
  const pts: [number, number][] = [[40, 150], [70, 125], [95, 138], [125, 98], [150, 82], [168, 52]];
  // cumulative lengths
  const lens: number[] = [0];
  for (let i = 1; i < pts.length; i++) {
    lens.push(lens[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  }
  const total = lens[lens.length - 1];
  const t = Math.max(0, Math.min(1, draw)) * total;
  let d = `M${pts[0][0]} ${pts[0][1]}`;
  let tip = pts[0];
  for (let i = 1; i < pts.length; i++) {
    if (t >= lens[i]) {
      d += ` L${pts[i][0]} ${pts[i][1]}`;
      tip = pts[i];
    } else if (t > lens[i - 1]) {
      const f = (t - lens[i - 1]) / (lens[i] - lens[i - 1]);
      tip = [pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * f, pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * f];
      d += ` L${tip[0]} ${tip[1]}`;
      break;
    }
  }
  const a = Math.atan2(pts[5][1] - pts[4][1], pts[5][0] - pts[4][0]) * 180 / Math.PI;
  return (
    <g strokeLinecap="round" strokeLinejoin="round" fill="none">
      <path d="M30 30 L30 165 L180 165" stroke={c.primary} strokeWidth={sw} />
      <path d="M30 135 L180 135 M30 105 L180 105 M30 75 L180 75" stroke={c.border} strokeWidth={sw} opacity={0.35} />
      <path d={d} stroke={c.primary} strokeWidth={sw} />
      <g transform={`translate(${pts[5][0]} ${pts[5][1]}) rotate(${a})`} opacity={draw > 0.97 ? 1 : 0}>
        <path d="M-12 -9 L0 0 L-12 9" stroke={c.primary} strokeWidth={sw} />
      </g>
      <circle cx={pts[3][0]} cy={pts[3][1]} r={0} />
      <g opacity={peak} transform={`translate(${pts[5][0] - 12} ${pts[5][1] + 10 - 0}) scale(${0.4 + 0.6 * peak})`}>
        <circle r={13} stroke={c.accent} strokeWidth={sw} opacity={0.5} />
        <circle r={6} fill={c.accent} stroke={c.primary} strokeWidth={sw} />
      </g>
    </g>
  );
}

