export default function StarRating({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const fill = p.fill ?? 0;
  const pop = p.pop ?? 0;
  const pts = (cx: number, cy: number, R: number, r: number) => {
    const a: string[] = [];
    for (let i = 0; i < 10; i++) {
      const ang = -Math.PI / 2 + (i * Math.PI) / 5;
      const rad = i % 2 === 0 ? R : r;
      a.push(`${(cx + rad * Math.cos(ang)).toFixed(2)},${(cy + rad * Math.sin(ang)).toFixed(2)}`);
    }
    return a.join(" ");
  };
  const stars = [0, 1, 2, 3, 4].map((i) => {
    const f = Math.max(0, Math.min(1, fill * 5 - i));
    const local = Math.max(0, Math.min(1, pop * 1.6 - i * 0.15));
    const lift = Math.sin(local * Math.PI) * 8 + local * 8;
    const cx = 32 + i * 34;
    const cy = 104 - lift;
    const s = 0.4 + 0.6 * f;
    return (
      <g key={i}>
        <ellipse cx={cx} cy={140} rx={12 - lift / 3} ry={2.5} fill={c.black} opacity={0.1} />
        <polygon points={pts(cx, cy, 16, 7)} fill="none" stroke={c.primary} strokeWidth={sw} strokeLinejoin="round" />
        <g transform={`translate(${cx} ${cy}) scale(${s}) translate(${-cx} ${-cy})`} opacity={f > 0 ? 1 : 0}>
          <polygon points={pts(cx, cy, 16, 7)} fill={c.accent} stroke={c.accent} strokeWidth={sw} strokeLinejoin="round" />
        </g>
      </g>
    );
  });
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
